f=p/'client/src/layouts/AppLayout.jsx'; f.write_text('''import React from 'react';
import {NavLink,Outlet,useNavigate,useLocation,Navigate} from 'react-router-dom';
import {LayoutDashboard,Hotel,BedDouble,CalendarDays,Users,Contact,ReceiptText,ClipboardCheck,Wrench,ConciergeBell,MessageSquare,ChartNoAxesCombined,Bell,Settings,LogOut,Menu,X,ChevronDown,Globe} from 'lucide-react';
import {setToken} from '../api/client';import {useAuth} from '../routes/AuthContext';
const allNav=[['Overview','/workspace',LayoutDashboard,['admin','manager','receptionist','housekeeping','maintenance']],['Hotel properties','/workspace/hotels',Hotel,['admin','manager']],['Rooms & inventory','/workspace/rooms',BedDouble,['admin','manager','receptionist','housekeeping','maintenance']],['Reservations','/workspace/reservations',CalendarDays,['admin','manager','receptionist']],['Guests','/workspace/guests',Users,['admin','manager','receptionist']],['Staff','/workspace/staff',Contact,['admin','manager']],['Billing','/workspace/billing',ReceiptText,['admin','manager','receptionist']],['Housekeeping','/workspace/housekeeping',ClipboardCheck,['admin','manager','receptionist','housekeeping']],['Maintenance','/workspace/maintenance',Wrench,['admin','manager','maintenance','receptionist']],['Guest Services','/workspace/services',ConciergeBell,['admin','manager','receptionist','housekeeping']],['Feedback','/workspace/feedback',MessageSquare,['admin','manager','receptionist']],['Reports','/workspace/reports',ChartNoAxesCombined,['admin','manager']],['Notifications','/workspace/notifications',Bell,['admin','manager','receptionist','housekeeping','maintenance']],['Settings','/workspace/settings',Settings,['admin','manager']]];
export default function AppLayout(){const {user,logout}=useAuth();const [mobile,setMobile]=React.useState(false);const navigate=useNavigate(),location=useLocation();const nav=allNav.filter(item=>item[3].includes(user?.role||'guest'));const allowed=nav.some(([,path])=>path===location.pathname)||(location.pathname==='/workspace'&&nav.some(([,path])=>path==='/workspace'));if(user?.role==='guest')return <Navigate to="/my-stays" replace/>;if(!allowed)return <Navigate to={nav[0]?.[1]||'/welcome'} replace/>;function signOut(){setToken(null);logout();navigate('/welcome')}return <div className="app-shell"><aside className={`sidebar ${mobile?'sidebar-open':''}`}><div className="brand"><div className="brand-mark">L<span>S</span></div><div><b>LuxuryStay</b><small>HOSPITALITY GROUP</small></div><button className="mobile-close" onClick={()=>setMobile(false)}><X/></button></div><div className="hotel-switch"><span className="hotel-avatar"><Hotel size={17}/></span><div><b>LuxuryStay Workspace</b><small>{(user?.role||'staff').toUpperCase()} PANEL</small></div><ChevronDown size={15}/></div><div className="nav-label">WORKSPACE</div><nav>{nav.map(([label,path,Icon])=><NavLink key={path} to={path} end={path==='/workspace'} onClick={()=>setMobile(false)} className={({isActive})=>`nav-link ${isActive?'active':''}`}><Icon size={18}/><span>{label}</span>{label==='Notifications'&&<i className="nav-dot"/>}</NavLink>)}</nav><div className="sidebar-bottom"><div className="help-card"><div className="help-icon">✦</div><b>Need assistance?</b><p>Contact your system administrator for support.</p><button className="text-link" onClick={()=>navigate('/welcome')}><Globe size={13}/> Public website</button></div><button className="profile" onClick={signOut}><div className="avatar">{user?.name?.slice(0,1)||'A'}</div><div className="profile-info"><b>{user?.name||'Team member'}</b><small>{user?.role||'staff'}</small></div><LogOut size={17}/></button></div></aside><div className="main-column"><header className="topbar"><button className="menu-toggle" onClick={()=>setMobile(!mobile)}><Menu/></button><div className="crumb">Workspace <span>/</span> <b>{nav.find(n=>n[1]===location.pathname)?.[0]||'Hotel operations'}</b></div><div className="topbar-right"><span className="live-dot"/> <span className="system-label">Secure workspace</span><button className="icon-button" title="Notifications" onClick={()=>navigate('/workspace/notifications')}><Bell size={19}/></button><div className="top-avatar">{user?.name?.slice(0,1)||'A'}</div></div></header><main className="page-content"><Outlet/></main><footer className="footer"><span>© {new Date().getFullYear()} LuxuryStay Hospitality</span><span>HOTEL OPERATIONS PLATFORM <i>•</i> {String(user?.role||'staff').toUpperCase()} PANEL</span></footer></div></div>}
''')
