(p/'client/src/pages/CustomerPortal.jsx').write_text('''import React from 'react';import {Link,useNavigate} from 'react-router-dom';import {ArrowRight,CalendarDays,LogOut,UserRound,ShieldCheck,Hotel,Clock3,ClipboardList} from 'lucide-react';import {api,setToken} from '../api/client';import {useAuth} from '../routes/AuthContext';import {Notice,Loading} from '../components/UI';
const API_ORIGIN=(import.meta.env.VITE_API_URL||'http://localhost:5000/api').replace(/\\/api\\/?$/,'');const money=n=>new Intl.NumberFormat('en-PK',{style:'currency',currency:'PKR',maximumFractionDigits:0}).format(n||0);const photo=r=>{const src=r?.imageUrls?.[0]||r?.imageUrl;return src?(src.startsWith('http')?src:`${API_ORIGIN}${src}`):'https://images.unsplash.com/photo-1611892440504-42a792e24d32?auto=format&fit=crop&w=900&q=80'};
export default function CustomerPortal(){const {user,logout,login}=useAuth();const [bookings,setBookings]=React.useState([]),[busy,setBusy]=React.useState(false),[error,setError]=React.useState('');const navigate=useNavigate();React.useEffect(()=>{if(user?.role==='guest'){setBusy(true);api('/guest/bookings').then(d=>setBookings(d.data||d||[])).catch(e=>setError(e.message)).finally(()=>setBusy(false));}},[user]);function signOut(){setToken(null);logout();navigate('/')}return <div className="guest-portal"><header className="portal-nav"><Link to="/" className="public-brand"><span className="brand-mark">L<span>S</span></span><span><b>LuxuryStay</b><small>STAY A LITTLE EXTRAORDINARY</small></span></Link><nav><Link to="/">Home</Link><Link to="/rooms">Explore rooms</Link>{user?<button onClick={signOut}><LogOut size={15}/> Sign out</button>:<Link className="nav-login" to="/login">Sign in</Link>}</nav></header><section className="portal-welcome"><div><span className="eyebrow">YOUR LUXURYSTAY</span><h1>{user?`Welcome back, ${user.name?.split(' ')[0]}.`:'Your stays, all in one place.'}</h1><p>{user?'Your booking details and future getaways, gathered in one calm place.':'Sign in to see your saved booking history — or browse and book without an account.'}</p></div><div className="portal-welcome-mark">LS</div></section>{!user?<section className="portal-signin-card"><div className="portal-signin-icon"><UserRound/></div><h2>Make it personal.</h2><p>Sign in to view reservations made with your account email. Guest bookings are saved too — create an account using the same email to connect your stay history.</p><div><Link className="gold-button" to="/login">Sign in <ArrowRight size={16}/></Link><Link className="member-guest-link" to="/register">Create account</Link></div><Link className="back-public" to="/rooms">Continue booking as a guest</Link></section>:user.role!=='guest'?<section className="portal-signin-card"><h2>You’re signed in to the team workspace.</h2><p>Use your staff tools to manage the hotel operation.</p><Link className="gold-button" to="/workspace">Open workspace <ArrowRight size={16}/></Link></section>:<main className="portal-main"><div className="portal-stats"><article><span><ClipboardList/></span><div><b>{bookings.length}</b><small>Reservations found</small></div></article><article><span><CalendarDays/></span><div><b>{bookings.filter(b=>['confirmed','checked_in'].includes(b.status)).length}</b><small>Upcoming / active stays</small></div></article><article><span><ShieldCheck/></span><div><b>Guest access</b><small>Private account</small></div></article></div><Notice error={error}/><div className="portal-section-heading"><div><span className="eyebrow">YOUR JOURNEY</span><h2>Booking history</h2><p>Bookings connected to {user.email}</p></div><Link className="gold-button" to="/rooms">Plan another stay <ArrowRight size={15}/></Link></div>{busy?<Loading/>:bookings.length?<div className="guest-bookings">{bookings.map(b=><article className="guest-booking-card" key={b._id}><img src={photo(b.roomId)} alt="Booked room"/><div className="guest-booking-details"><div className="guest-booking-top"><span className="booking-ref">{b.reference}</span><span className={`guest-status status-${b.status?.replaceAll('_','-')}`}>{b.status?.replaceAll('_',' ')}</span></div><h3>{b.roomId?.roomTypeId?.name||'LuxuryStay room'}{b.roomId?.number?` · Room ${b.roomId.number}`:''}</h3><p><Hotel size={14}/> {b.hotelId?.name||'LuxuryStay'} {b.hotelId?.city?`· ${b.hotelId.city}`:''}</p><div className="guest-stay-dates"><span><small>CHECK IN</small><b>{new Date(b.checkIn).toLocaleDateString()}</b></span><span><small>CHECK OUT</small><b>{new Date(b.checkOut).toLocaleDateString()}</b></span><span><small>TOTAL</small><b>{money(b.total)}</b></span></div></div></article>)}</div>:<section className="portal-empty"><div><Clock3 size={30}/></div><h3>Your next getaway is waiting.</h3><p>No bookings are linked to this email yet. Explore available rooms and make your first reservation.</p><Link className="gold-button" to="/rooms">Find your stay <ArrowRight size={15}/></Link></section>}<div className="portal-benefits"><div><ShieldCheck/><span><b>Booking history</b><small>Keep your stays in one place.</small></span></div><div><UserRound/><span><b>Faster reservations</b><small>Your details are ready next time.</small></span></div><div><CalendarDays/><span><b>Stay at a glance</b><small>See dates, room and reference.</small></span></div></div></main>}<footer className="public-footer portal-footer"><Link to="/" className="public-brand"><span className="brand-mark">L<span>S</span></span><span><b>LuxuryStay</b><small>STAY A LITTLE EXTRAORDINARY</small></span></Link><span>© {new Date().getFullYear()} LuxuryStay Hospitality</span><Link to="/rooms">Explore stays</Link></footer></div>}
''')
